<?php session_start(); if(!isset($_SESSION['secreto']))$_SESSION['secreto']=random_int(1,10); if(!isset($_SESSION['intentos']))$_SESSION['intentos']=0; $resultado=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $guess=filter_input(INPUT_POST,'numero',FILTER_VALIDATE_INT); if($guess===false||$guess===null||$guess<1||$guess>10){$resultado='Ingresa un número entero del 1 al 10.';}else{$_SESSION['intentos']++;if($guess===$_SESSION['secreto']){$resultado='¡Correcto! Adivinaste el número en '.$_SESSION['intentos'].' intento(s).';$_SESSION['ganado']=true;}elseif($_SESSION['intentos']>=3){$resultado='Se terminaron las oportunidades. El número era '.$_SESSION['secreto'].'.';$_SESSION['fin']=true;}else{$resultado=$guess<$_SESSION['secreto']?'El número secreto es mayor.':'El número secreto es menor.';}}} if(isset($_POST['nuevo'])){$_SESSION['secreto']=random_int(1,10);$_SESSION['intentos']=0;unset($_SESSION['ganado'],$_SESSION['fin']);$resultado='Nueva partida. ¡Inténtalo!';} $bloqueado=isset($_SESSION['ganado'])||isset($_SESSION['fin']); ?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ejercicio 04 | Adivinanzas</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><header class="topbar"><a class="brand" href="../index.php"><span class="brand-mark">P</span> PWATAREA3</a><a class="back" href="../index.php">← Volver al inicio</a></header><main class="page-wrap"><span class="eyebrow">EJERCICIO 04</span><section class="panel"><h1>Juego de adivinanzas</h1><p class="muted">Adivina el número secreto del 1 al 10. Tienes tres oportunidades. PHP genera el número y conserva el estado de la partida; JavaScript valida la entrada.</p><?php if($resultado): ?><p class="notice game-result"><?=htmlspecialchars($resultado)?></p><?php endif; ?><p><b>Intentos:</b> <?= (int)$_SESSION['intentos'] ?> / 3</p><form method="post" class="inline" id="guessForm"><input type="number" name="numero" id="numero" min="1" max="10" placeholder="Tu número" required <?= $bloqueado?'disabled':'' ?>><button class="btn-submit" <?= $bloqueado?'disabled':'' ?>>Adivinar</button></form><form method="post" style="margin-top:15px"><button class="btn-submit" name="nuevo" value="1">Nueva partida</button></form></section></main><script>document.getElementById('guessForm').addEventListener('submit',e=>{const n=Number(document.getElementById('numero').value);if(!Number.isInteger(n)||n<1||n>10){e.preventDefault();alert('Ingresa un número entero entre 1 y 10.');}});</script></body></html>